<script setup>
import { Link, router } from '@inertiajs/vue3';import {reactive}from'vue';import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props=defineProps({words:Object,search:String,status:String});const filters=reactive({q:props.search||'',status:props.status||''});function filter(){router.get('/admin/words',filters,{preserveState:true,replace:true});}
</script>
<template><AdminLayout title="单词管理" section="内容管理 / 单词管理" description="管理单词资料、详解和发布状态。"><template #actions><Link href="/admin/words/create"><el-button type="primary">＋ 新建单词</el-button></Link></template><section class="card"><form class="filter-bar" @submit.prevent="filter"><el-input v-model="filters.q" class="search" clearable placeholder="搜索单词或释义" @keyup.enter="filter"/><el-select v-model="filters.status"><el-option label="全部状态" value=""/><el-option label="草稿" value="draft"/><el-option label="已发布" value="published"/></el-select><el-button type="primary" native-type="submit">筛选</el-button><el-button v-if="filters.q||filters.status" text type="primary" @click="filters.q='';filters.status='';filter()">清空</el-button></form><div v-if="!words.data.length" class="empty-state"><strong>{{ filters.q||filters.status?'没有匹配的单词':'还没有单词' }}</strong></div><div v-else class="table-wrap"><el-table :data="words.data" stripe><el-table-column label="ID" width="80"><template #default="scope"><span class="badge-id">#{{scope.row.id}}</span></template></el-table-column><el-table-column label="单词" min-width="150"><template #default="scope"><div class="table-primary">{{scope.row.headword}}</div><div class="table-secondary">{{scope.row.ipa}}</div></template></el-table-column><el-table-column label="词性" width="110"><template #default="scope">{{scope.row.part_of_speech||'—'}}</template></el-table-column><el-table-column prop="meaning" label="释义" min-width="190" show-overflow-tooltip/><el-table-column label="状态" width="110"><template #default="scope"><el-tag :type="scope.row.status==='published'?'success':'info'" effect="light">{{scope.row.status==='published'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column label="最后更新" min-width="160"><template #default="scope">{{scope.row.updated_at||'—'}}</template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="scope"><Link :href="`/admin/words/${scope.row.id}/edit`"><el-button link type="primary">编辑</el-button></Link></template></el-table-column></el-table></div><div v-if="words.data.length" class="table-footer"><span>共 {{words.total}} 个</span><el-pagination background layout="prev, pager, next" :current-page="words.current_page" :page-count="words.last_page" @current-change="page=>router.get('/admin/words',{...filters,page},{preserveState:true,replace:true})"/></div></section></AdminLayout></template>
